#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

long long gcdOf(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> ops(q, vector<long long>(3));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> ops[i][j];
        }
    }

    long long size = 1;
    while (size < n) size *= 2;
    vector<long long> tree(2 * size, 0);
    for (long long i = 0; i < n; i++) tree[size + i] = a[i];
    for (long long v = size - 1; v >= 1; v--) tree[v] = gcdOf(tree[2 * v], tree[2 * v + 1]);
    string out;
    for (long long k = 0; k < q; k++) {
        long long kind = ops[k][0], x = ops[k][1], y = ops[k][2];
        if (kind == 1) {
            long long v = size + x - 1;
            tree[v] = y;
            for (v /= 2; v >= 1; v /= 2) tree[v] = gcdOf(tree[2 * v], tree[2 * v + 1]);
        } else {
            long long lo = size + x - 1, hi = size + y, res = 0;
            while (lo < hi) {
                if (lo & 1) res = gcdOf(res, tree[lo++]);
                if (hi & 1) res = gcdOf(res, tree[--hi]);
                lo /= 2;
                hi /= 2;
            }
            if (!out.empty()) out += " ";
            out += to_string(res);
        }
    }
    cout << out << "\n";

    return 0;
}

