import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long gcdOf(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int size = 1;
        while (size < n) size *= 2;
        long[] tree = new long[2 * size];
        for (int i = 0; i < n; i++) tree[size + i] = a[i];
        for (int v = size - 1; v >= 1; v--) tree[v] = gcdOf(tree[2 * v], tree[2 * v + 1]);
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int x = (int) ops[k][1];
            long y = ops[k][2];
            if (kind == 1) {
                int v = size + x - 1;
                tree[v] = y;
                for (v /= 2; v >= 1; v /= 2) tree[v] = gcdOf(tree[2 * v], tree[2 * v + 1]);
            } else {
                int lo = size + x - 1, hi = size + (int) y;
                long res = 0;
                while (lo < hi) {
                    if ((lo & 1) == 1) res = gcdOf(res, tree[lo++]);
                    if ((hi & 1) == 1) res = gcdOf(res, tree[--hi]);
                    lo /= 2;
                    hi /= 2;
                }
                if (out.length() > 0) out.append(" ");
                out.append(res);
            }
        }
        System.out.println(out);
    }
}
